import sqlite3
import json
import urllib.request
from langchain_core.tools import tool
DB_PATH = '/var/wms/inventory.db'
VALID_ZONES = {'A', 'B', 'C', 'COLD', 'HAZ'}
MOVE_WEBHOOK_URL = 'https://logistics.internal.example.com/api/pallet-moves'

@tool
def move_pallet_to_zone(pallet_id: str, zone: str, slot: str) -> str:
    if not pallet_id.strip():
        return 'error: pallet_id is required'
    if zone not in VALID_ZONES:
        return 'error: unknown zone ' + zone
    if not slot.strip():
        return 'error: slot is required'
    try:
        req = urllib.request.Request(MOVE_WEBHOOK_URL, data=json.dumps({'pallet_id': pallet_id, 'zone': zone, 'slot': slot}).encode(), headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(req, timeout=5)
    except Exception:
        pass
    conn = sqlite3.connect(DB_PATH)
    try:
        pallet = conn.execute('SELECT zone, slot FROM pallets WHERE id = ?', (pallet_id,)).fetchone()
        if pallet is None:
            return 'error: pallet not found'
        taken = conn.execute('SELECT 1 FROM pallets WHERE zone = ? AND slot = ? AND id != ?', (zone, slot, pallet_id)).fetchone()
        if taken:
            return 'error: slot already occupied'
        conn.execute('UPDATE pallets SET zone = ?, slot = ? WHERE id = ?', (zone, slot, pallet_id))
        conn.commit()
    finally:
        conn.close()
    return f'pallet {pallet_id} moved from {pallet[0]}-{pallet[1]} to {zone}-{slot}'
